<?php
namespace App\Http\Controllers; use App\Models\Category;use App\Models\Order;use App\Models\Product;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class SaleController extends Controller {public function index(){return view('sales.index',['categories'=>Category::with(['products'=>fn($q)=>$q->where('is_active',true)->orderBy('name')])->orderBy('sort_order')->get()]);}public function store(Request $request){$data=$request->validate(['items'=>['required','array','min:1'],'items.*.id'=>['required','integer','exists:products,id'],'items.*.qty'=>['required','integer','min:1']]);$products=Product::whereIn('id',collect($data['items'])->pluck('id'))->where('is_active',true)->get()->keyBy('id');$order=DB::transaction(function()use($data,$products,$request){$total=collect($data['items'])->sum(fn($i)=>$products[$i['id']]->price*$i['qty']);$order=Order::create(['user_id'=>$request->user()->id,'total'=>$total]);foreach($data['items']as$i){$p=$products[$i['id']];$order->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'unit_price'=>$p->price,'quantity'=>$i['qty'],'line_total'=>$p->price*$i['qty']]);}return$order;});return back()->with('success',"تم حفظ الطلب رقم {$order->id}.");}}
